package com.smartliving.iot.controller;

import com.smartliving.iot.dto.ThermostatScheduleDto;
import com.smartliving.iot.entity.SmartThermostat;
import com.smartliving.iot.repository.ThermostatRepository;
import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/iot/climate")
public class DeviceScheduleController {

    private final ThermostatRepository thermostatRepository;

    public DeviceScheduleController(ThermostatRepository thermostatRepository) {
        this.thermostatRepository = thermostatRepository;
    }

    @PatchMapping("/devices/{deviceId}/schedule")
    public ResponseEntity<String> updateThermostatSchedule(
            @PathVariable String deviceId,
            @Valid @RequestBody ThermostatScheduleDto scheduleDto,
            Authentication authentication) {
        SmartThermostat thermostat = thermostatRepository.findByDeviceId(deviceId)
                .orElseThrow(() -> new IllegalArgumentException("Device not registered"));
        if (!thermostat.getResidentUsername().equals(authentication.getName())) {
            throw new AccessDeniedException("Resident not authorized to adjust device " + deviceId);
        }
        thermostat.setTargetTempCelsius(scheduleDto.getTargetTempCelsius());
        thermostat.setOperatingMode(scheduleDto.getMode());
        thermostatRepository.save(thermostat);
        return ResponseEntity.ok("HVAC schedule updated");
    }
}
